/** Internal IR discriminator shared by native JSX factories and codecs. */
export const NATIVE_NODE = Symbol.for("copilotkit.channels-ui.NativeNode");
/** Create one provider-tagged IR node without serializing its named JSX slots. */
export function createNativeNode(provider, nativeKind, nativeType, props) {
    return {
        type: NATIVE_NODE,
        props: { ...props, provider, nativeKind, nativeType },
    };
}
/** Return whether a rendered Channel IR node belongs to a provider catalog. */
export function isNativeNode(node) {
    return (typeof node === "object" &&
        node !== null &&
        node.type === NATIVE_NODE &&
        typeof node.props?.provider ===
            "string" &&
        typeof node.props?.nativeKind ===
            "string" &&
        typeof node.props?.nativeType ===
            "string");
}
